    for(int ic=0;ic<1;++ic) Gd2[2+ic] = Rl[1]*fd2[1+ic] + Rl[4]*fd2[2+ic] + Rl[7]*fd2[3+ic];
    for(int ic=0;ic<1;++ic) Gd2[3+ic] = Rl[2]*fd2[1+ic] + Rl[5]*fd2[2+ic] + Rl[8]*fd2[3+ic];
  }
  double Gk[12];
  for(int ic=0;ic<3;++ic) Gk[0+ic] = fkt[0+ic];
  { // k=1 lam=1
