    for(int ic=0;ic<3;++ic) Gk[6+ic] = Rl[1]*fkt[3+ic] + Rl[4]*fkt[6+ic] + Rl[7]*fkt[9+ic];
    for(int ic=0;ic<3;++ic) Gk[9+ic] = Rl[2]*fkt[3+ic] + Rl[5]*fkt[6+ic] + Rl[8]*fkt[9+ic];
  }
  double Fb_[3]; gen_boys_dev_g(2, eta*Rn*Rn, Fb_);
  const double m2 = -2.0*eta;
  const double s0_0_0_0 = Fb_[0];
  const double s1_0_0_0 = m2*Fb_[1];
  const double s2_0_0_0 = m2*m2*Fb_[2];
  const double s0_0_0_1 = Rn*s1_0_0_0;
  const double s1_0_0_1 = Rn*s2_0_0_0;
  const double s0_2_0_0 = 1.0*s1_0_0_0;
  const double s0_0_2_0 = 1.0*s1_0_0_0;
  const double s0_0_0_2 = Rn*s1_0_0_1 + 1.0*s1_0_0_0;
  const double h0_0 = 0.9999999999999997*s0_0_0_0;
  const double h1_0 = 1.0000000000000004*s0_0_0_1;
  const double h2_0 = 0.9999999999999997*s0_2_0_0 + 0.9999999999999997*s0_0_2_0 + 0.9999999999999997*s0_0_0_2;
  const double h2_1 = -0.500000000000001*s0_2_0_0 + -0.4999999999999994*s0_0_2_0 + 0.9999999999999999*s0_0_0_2;
  const double hz0_0 = 0.9999999999999997*s0_0_0_1;
  const double hz1_0 = 1.0000000000000004*s0_0_0_2;
  const double t0_0 = 0.9999999999999998*h0_0;
  const double t0_2 = -0.9999999999999996*h1_0;
  const double t1_1 = -0.3333333333333339*h2_0 + 0.3333333333333338*h2_1;
  const double t2_0 = 0.9999999999999996*h1_0;
  const double t2_2 = -0.33333333333333387*h2_0 + -0.6666666666666672*h2_1;
  const double t3_3 = -0.3333333333333334*h2_0 + 0.3333333333333333*h2_1;
  const double tz0_0 = 0.9999999999999998*hz0_0;
  const double tz0_2 = -0.9999999999999996*hz1_0;
  const double ox0_3 = 1.0000000000000002*t0_2;
  const double oy0_1 = 1.0000000000000002*t0_2;
