  for(int jc=0;jc<3;++jc) Ye[6+jc] = t2_0*Gk[0+jc] + t2_2*Gk[6+jc];
  for(int jc=0;jc<3;++jc) Ye[9+jc] = t3_3*Gk[9+jc];
