    double* o=accP1+ic*3;
    for(int jc=0;jc<3;++jc) o[jc] = g*y[jc]; }
  for(int ic=0;ic<1;++ic){ const double g=Gd1[1+ic];
    const double* y=Ye+3;
    double* o=accP1+ic*3;
    for(int jc=0;jc<3;++jc) o[jc] += g*y[jc]; }
  for(int ic=0;ic<1;++ic){ const double g=Gd1[2+ic];
