    double* o=accP2+ic*3;
    for(int jc=0;jc<3;++jc) o[jc] += g*y[jc]; }
  for(int ic=0;ic<1;++ic){ const double g=Gd2[3+ic];
    const double* y=Ye+9;
    double* o=accP2+ic*3;
    for(int jc=0;jc<3;++jc) o[jc] += g*y[jc]; }
