  for(int ic=0;ic<1;++ic){ const double g=Gb[0+ic];
    const double* y=Yz+0;
    double* o=accDz+ic*3;
    for(int jc=0;jc<3;++jc) o[jc] = g*y[jc]; }
  double accDx[3];
  for(int ic=0;ic<1;++ic){ const double g=Gb[0+ic];
    const double* y=Yx+0;
    double* o=accDx+ic*3;
    for(int jc=0;jc<3;++jc) o[jc] = g*y[jc]; }
  double accDy[3];
  for(int ic=0;ic<1;++ic){ const double g=Gb[0+ic];
