// grad3c_al_00_2: (00|2)' aligned three-piece (pair-local + radial + orientation)
__device__ __forceinline__ static void grad3c_al_00_2(const double* ft, const double* fdt, const double* fkt,
    double Rx, double Ry, double Rz, double eta, double pref,
    double* V, double* Pl, double* DR){
