// grad3c_al_30_1: (30|1)' aligned three-piece (pair-local + radial + orientation)
__device__ __forceinline__ static void grad3c_al_30_1(const double* ft, const double* fdt, const double* fkt,
    double Rx, double Ry, double Rz, double eta, double pref,
    double* V, double* Pl, double* DR){
  const double Rn = sqrt(Rx*Rx+Ry*Ry+Rz*Rz);
  const double ir = 1.0/Rn;  // caller guarantees Rn > threshold on this route
  const double zx=Rx*ir, zy=Ry*ir, zz=Rz*ir;
