  const double r1_12 = R3[6];
  const double r1_20 = R3[1];
  const double r1_21 = R3[2];
  const double r1_22 = R3[0];
  Rl[0] = r1_00;
  Rl[1] = r1_01;
  Rl[2] = r1_02;
  Rl[3] = r1_10;
